# Generated by build.py from recipe.yml for recipe http-list-a-directory. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site/sub', 'other' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/sub/a.txt'), "a`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/.hidden'), "not for you`n")
[IO.File]::WriteAllText((Join-Path $PWD 'other/readme.txt'), "read me`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--list-directories', 'http://127.0.0.1:8080/', 'ws://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe ws://127.0.0.1:8081/ } finally { Stop-Process $server0 }
